  ('pages.confidentialite.auto.list_item.1ebd0ql', '/confidentialite', 'list_item', '<strong>Données de connexion :</strong> adresse IP, logs de connexion, pages consultées (via les cookies).'),
  ('pages.confidentialite.auto.list_item.1fbxhue', '/confidentialite', 'list_item', '<strong>Données d''identification :</strong> nom, prénom, adresse e-mail, numéro de téléphone, entreprise.'),
  ('pages.confidentialite.auto.list_item.1kxx108', '/confidentialite', 'list_item', 'Vous fournir des estimations via notre simulateur de revenus.'),
