  ('pages.expertises.data-ia.auto.paragraph.1dttx4h', '/expertises/data-ia', 'paragraph', 'Data Analyst'),
  ('pages.expertises.data-ia.auto.paragraph.1e907ml', '/expertises/data-ia', 'paragraph', 'Profils accompagnés'),
  ('pages.expertises.data-ia.auto.paragraph.1hkia6c', '/expertises/data-ia', 'paragraph', 'Une mission data ou IA ne se résume pas au choix d’un modèle ou d’un outil. Elle part d’un besoin métier, de données accessibles et gouvernées, puis se poursuit jusqu’au déploiement, au suivi et à l’adoption.'),
  ('pages.expertises.data-ia.auto.paragraph.1jp9yb7', '/expertises/data-ia', 'paragraph', 'Data Governance Specialist'),
  ('pages.expertises.data-ia.auto.paragraph.1nceca1', '/expertises/data-ia', 'paragraph', 'Le cadre The Porters'),
  ('pages.expertises.data-ia.auto.paragraph.1nzigs2', '/expertises/data-ia', 'paragraph', 'Missions'),
  ('pages.expertises.data-ia.auto.paragraph.1pk9fed', '/expertises/data-ia', 'paragraph', 'Cadre contractuel avec l’entreprise cliente'),
  ('pages.expertises.data-ia.auto.paragraph.1vbfg3j', '/expertises/data-ia', 'paragraph', 'Data Engineer'),
  ('pages.expertises.data-ia.auto.paragraph.1w2799l', '/expertises/data-ia', 'paragraph', 'Consultant stratégie IA'),
  ('pages.expertises.data-ia.auto.paragraph.1ydlwa6', '/expertises/data-ia', 'paragraph', 'AI Architect'),
  ('pages.expertises.data-ia.auto.paragraph.2cyic5', '/expertises/data-ia', 'paragraph', 'Machine Learning Engineer'),
  ('pages.expertises.data-ia.auto.paragraph.d9td0c', '/expertises/data-ia', 'paragraph', 'Lecture du TJM, de la durée et des conditions de mission'),
  ('pages.expertises.data-ia.auto.paragraph.dftvvf', '/expertises/data-ia', 'paragraph', 'Identifier les tâches où l’IA apporte un gain réel, puis mesurer sa qualité et ses limites.'),
  ('pages.expertises.data-ia.auto.paragraph.f0xscj', '/expertises/data-ia', 'paragraph', 'Data engineers, data scientists, consultants BI, ML engineers et architectes IA conservent leur autonomie commerciale tout en déléguant le cadre contractuel, la facturation et la paie.'),
  ('pages.expertises.data-ia.auto.paragraph.grre9i', '/expertises/data-ia', 'paragraph', 'Documenter les flux, la gouvernance et les responsabilités afin de pérenniser les solutions au-delà du prototype.'),
  ('pages.expertises.data-ia.auto.paragraph.hbhj9e', '/expertises/data-ia', 'paragraph', 'Vous pilotez l’expertise et la relation opérationnelle. The Porters porte le cadre salarial, contractuel et administratif.'),
  ('pages.expertises.data-ia.auto.paragraph.i0qp33', '/expertises/data-ia', 'paragraph', 'Point de contact administratif pendant l’intervention'),
  ('pages.expertises.data-ia.auto.paragraph.ko6uzh', '/expertises/data-ia', 'paragraph', 'Le portage salarial convient aux experts mobilisés sur une phase précise ou sur un programme plus long, sans leur imposer de créer immédiatement une structure juridique.'),
  ('pages.expertises.data-ia.auto.paragraph.m29l4s', '/expertises/data-ia', 'paragraph', 'Prochaine étape'),
  ('pages.expertises.data-ia.auto.paragraph.mnucie', '/expertises/data-ia', 'paragraph', 'Facturation, paie et suivi des frais validés'),
  ('pages.expertises.data-ia.auto.paragraph.n1ciig', '/expertises/data-ia', 'paragraph', 'Produire des données fiables et des analyses lisibles pour soutenir les arbitrages opérationnels.'),
