  ('pages.expertises.product-project-management.auto.list_item.vmxen7', '/expertises/product-project-management', 'list_item', '<span class="mt-2 h-2 w-2 shrink-0 rounded-full bg-porters-gold"></span>Cadrage et priorisation'),
  ('pages.expertises.product-project-management.auto.list_item.wnqnad', '/expertises/product-project-management', 'list_item', '<span class="mt-2 h-1.5 w-1.5 shrink-0 rounded-full bg-porters-gold"></span>Discovery produit'),
  ('pages.expertises.product-project-management.auto.list_item.x3d3np', '/expertises/product-project-management', 'list_item', '<span class="mt-2 h-2 w-2 shrink-0 rounded-full bg-porters-gold"></span>Gouvernance de programme'),
  ('pages.expertises.product-project-management.auto.paragraph.10n12s0', '/expertises/product-project-management', 'paragraph', 'Product &amp; Project Management · Consultants IT'),
  ('pages.expertises.product-project-management.auto.paragraph.11j82hg', '/expertises/product-project-management', 'paragraph', 'Change Manager'),
  ('pages.expertises.product-project-management.auto.paragraph.16b4gq', '/expertises/product-project-management', 'paragraph', 'Product Owner'),
  ('pages.expertises.product-project-management.auto.paragraph.17ysdw7', '/expertises/product-project-management', 'paragraph', 'Les profils produit et projet relient la stratégie, les besoins métiers, les équipes techniques et les contraintes de delivery. Leur valeur tient autant à la décision qu’à la coordination et à la qualité du suivi.'),
  ('pages.expertises.product-project-management.auto.paragraph.18ahffj', '/expertises/product-project-management', 'paragraph', 'Product &amp; Project Management'),
  ('pages.expertises.product-project-management.auto.paragraph.193cqcp', '/expertises/product-project-management', 'paragraph', 'Accompagnement'),
  ('pages.expertises.product-project-management.auto.paragraph.1bwi7b4', '/expertises/product-project-management', 'paragraph', 'Enjeux de mission'),
  ('pages.expertises.product-project-management.auto.paragraph.1dowfo0', '/expertises/product-project-management', 'paragraph', 'Directeur de programme'),
  ('pages.expertises.product-project-management.auto.paragraph.1dttx4h', '/expertises/product-project-management', 'paragraph', 'Product Manager'),
  ('pages.expertises.product-project-management.auto.paragraph.1e907ml', '/expertises/product-project-management', 'paragraph', 'Profils accompagnés'),
  ('pages.expertises.product-project-management.auto.paragraph.1hkia6c', '/expertises/product-project-management', 'paragraph', 'Le portage salarial permet d’intervenir sur une transformation, un lancement produit ou un programme critique sans créer immédiatement sa propre société.'),
  ('pages.expertises.product-project-management.auto.paragraph.1jp9yb7', '/expertises/product-project-management', 'paragraph', 'Delivery Manager'),
  ('pages.expertises.product-project-management.auto.paragraph.1nceca1', '/expertises/product-project-management', 'paragraph', 'Le cadre The Porters'),
  ('pages.expertises.product-project-management.auto.paragraph.1nzigs2', '/expertises/product-project-management', 'paragraph', 'Missions'),
  ('pages.expertises.product-project-management.auto.paragraph.1pk9fed', '/expertises/product-project-management', 'paragraph', 'Contrats et facturation'),
  ('pages.expertises.product-project-management.auto.paragraph.1vbfg3j', '/expertises/product-project-management', 'paragraph', 'Chef de projet IT'),
  ('pages.expertises.product-project-management.auto.paragraph.1ydlwa6', '/expertises/product-project-management', 'paragraph', 'Business Analyst'),
  ('pages.expertises.product-project-management.auto.paragraph.2cyic5', '/expertises/product-project-management', 'paragraph', 'PMO'),
  ('pages.expertises.product-project-management.auto.paragraph.d9td0c', '/expertises/product-project-management', 'paragraph', 'Cadrage du TJM et du périmètre'),
  ('pages.expertises.product-project-management.auto.paragraph.dftvvf', '/expertises/product-project-management', 'paragraph', 'Suivre les jalons, les risques, les dépendances et les livrables sans alourdir le projet.'),
  ('pages.expertises.product-project-management.auto.paragraph.f0xscj', '/expertises/product-project-management', 'paragraph', 'Cadrez vos missions de pilotage produit, projet ou programme avec un statut salarié, tout en conservant votre autonomie de conseil et votre relation client.'),
  ('pages.expertises.product-project-management.auto.paragraph.grre9i', '/expertises/product-project-management', 'paragraph', 'Documenter les décisions et organiser le transfert de connaissances pour sécuriser la durée.'),
  ('pages.expertises.product-project-management.auto.paragraph.hbhj9e', '/expertises/product-project-management', 'paragraph', 'Vous pilotez l’expertise et la relation opérationnelle. The Porters porte le cadre salarial, contractuel et administratif.'),
  ('pages.expertises.product-project-management.auto.paragraph.i0qp33', '/expertises/product-project-management', 'paragraph', 'Interlocuteur administratif pendant la mission'),
  ('pages.expertises.product-project-management.auto.paragraph.m29l4s', '/expertises/product-project-management', 'paragraph', 'Prochaine étape'),
  ('pages.expertises.product-project-management.auto.paragraph.mnucie', '/expertises/product-project-management', 'paragraph', 'Paie et frais professionnels validés'),
  ('pages.expertises.product-project-management.auto.paragraph.n1ciig', '/expertises/product-project-management', 'paragraph', 'Clarifier les arbitrages, les responsabilités et les critères de réussite.'),
  ('pages.expertises.product-project-management.auto.paragraph.qrkykr', '/expertises/product-project-management', 'paragraph', 'Une question ?'),
  ('pages.expertises.product-project-management.auto.paragraph.xxeyen', '/expertises/product-project-management', 'paragraph', 'Méthode et impact'),
  ('pages.faq.auto.button.4nxp4q', '/faq', 'button', 'Accueil'),
  ('pages.faq.auto.button.bubqhp', '/faq', 'button', 'Contacter The Porters <span data-astro-cid-vagwt47q="">→</span>'),
  ('pages.faq.auto.button.vjh4vq', '/faq', 'button', 'Prendre rendez-vous <span data-astro-cid-vagwt47q="">→</span>'),
  ('pages.faq.auto.heading.16l9rai', '/faq', 'heading', 'Les réponses, avant l’appel.'),
  ('pages.faq.auto.heading.1ojq1ga', '/faq', 'heading', 'Entrée et sortie'),
  ('pages.faq.auto.heading.1t8h0lr', '/faq', 'heading', 'Comprendre le portage salarial'),
  ('pages.faq.auto.heading.1td4w85', '/faq', 'heading', 'Missions, congés et aléas'),
  ('pages.faq.auto.heading.exxvu3', '/faq', 'heading', 'Pour les entreprises'),
  ('pages.faq.auto.heading.ubeot0', '/faq', 'heading', 'Rémunération, frais et simulateur'),
  ('pages.faq.auto.heading.z1gt1c', '/faq', 'heading', 'Un conseiller reprend votre situation ligne par ligne.'),
  ('pages.faq.auto.paragraph.1152hnx', '/faq', 'paragraph', 'Thème'),
  ('pages.faq.auto.paragraph.12plv97', '/faq', 'paragraph', 'Thème'),
  ('pages.faq.auto.paragraph.148fmnm', '/faq', 'paragraph', 'Non. Il n’existe qu’un seul portage salarial. Que vous veniez d’un CDI, d’une micro-entreprise ou d’une SASU, le mécanisme est identique : un contrat de travail avec nous, un contrat de prestation avec votre client. Ce qui change, c’est votre point de départ, pas le dispositif.'),
  ('pages.faq.auto.paragraph.194b85v', '/faq', 'paragraph', 'Oui, avec un emploi salarié ou avec une retraite. Le cumul avec un emploi salarié suppose l’accord de votre employeur et un maximum de 48 heures de travail hebdomadaire, tous employeurs confondus.'),
  ('pages.faq.auto.paragraph.1aaihgg', '/faq', 'paragraph', '4 points'),
  ('pages.faq.auto.paragraph.1dlom95', '/faq', 'paragraph', 'Chaque mission est suivie par un binôme, avec un relais identifié. Aucun suivi ne dépend d’une seule personne.'),
  ('pages.faq.auto.paragraph.1fqgjsw', '/faq', 'paragraph', 'Vous mobilisez un expert autonome sans créer de relation d’emploi. Un seul contrat de prestation, une seule facture, et aucune gestion de paie de votre côté. C’est adapté à un besoin IT, data, cloud, cyber, projet ou transformation sur un périmètre défini.'),
  ('pages.faq.auto.paragraph.1g4le6s', '/faq', 'paragraph', 'Que se passe-t-il si je tombe malade ?'),
  ('pages.faq.auto.paragraph.1gaob0', '/faq', 'paragraph', 'Le portage salarial est-il reconnu légalement ?'),
  ('pages.faq.auto.paragraph.1grs8xm', '/faq', 'paragraph', 'Votre contrat de travail se poursuit, mais une période sans mission ne génère pas de chiffre d’affaires et donc pas de salaire. C’est précisément ce que le compte de trésorerie permet d’anticiper : lisser une période creuse avec de la réserve constituée pendant les mois facturés.'),
  ('pages.faq.auto.paragraph.1hyccjo', '/faq', 'paragraph', 'Sept services : la gestion de trésorerie, l’apport d’affaires, un interlocuteur identifié, la gestion administrative, la responsabilité civile professionnelle, l’accompagnement des formations et la garantie financière. Le détail figure sur la page Frais et rémunération.'),
  ('pages.faq.auto.paragraph.1id3tdl', '/faq', 'paragraph', 'FAQ'),
  ('pages.faq.auto.paragraph.1npwliw', '/faq', 'paragraph', 'Puis-je cumuler le portage avec autre chose ?'),
  ('pages.faq.auto.paragraph.1nue88i', '/faq', 'paragraph', 'Puis-je garder mes propres clients ?'),
  ('pages.faq.auto.paragraph.1ob8alt', '/faq', 'paragraph', 'Comment fonctionne le portage salarial ?'),
  ('pages.faq.auto.paragraph.1p1hbfs', '/faq', 'paragraph', 'Vous acquérez 2,5 jours ouvrés par mois, comme tout salarié. Ils vous sont versés chaque mois sur votre bulletin sous l’intitulé « Indemnités de congés payés », ou provisionnés sur votre compte de trésorerie si vous préférez maintenir votre rémunération pendant vos congés.'),
  ('pages.faq.auto.paragraph.1p2c0ap', '/faq', 'paragraph', 'Thème'),
  ('pages.faq.auto.paragraph.1qf8fpa', '/faq', 'paragraph', 'Comment se passe mon arrivée ?'),
  ('pages.faq.auto.paragraph.1qteiez', '/faq', 'paragraph', 'Trouvez-vous les missions à ma place ?'),
  ('pages.faq.auto.paragraph.1sadpup', '/faq', 'paragraph', '3 points'),
  ('pages.faq.auto.paragraph.1u629fc', '/faq', 'paragraph', 'Qui signe le contrat avec l’entreprise cliente ?'),
  ('pages.faq.auto.paragraph.1uw4r32', '/faq', 'paragraph', 'Et si mon interlocuteur est absent ?'),
  ('pages.faq.auto.paragraph.1va23mj', '/faq', 'paragraph', 'Quand suis-je payé ?'),
  ('pages.faq.auto.paragraph.1wpaaa1', '/faq', 'paragraph', 'Vous recevez une simulation chiffrée, le détail des frais et le mode opératoire de votre espace de gestion. Une intégration individuelle précise ensuite les contrats, l’activité mensuelle, la paie et vos contacts.'),
  ('pages.faq.auto.paragraph.1wppeyt', '/faq', 'paragraph', 'Oui. Vous vous constituez votre propre clientèle et vous en restez pleinement responsable. Vous choisissez vos missions et négociez vos tarifs, sans lien hiérarchique ni chez le client ni chez nous.'),
  ('pages.faq.auto.paragraph.1x729qq', '/faq', 'paragraph', 'À quoi sert le compte de trésorerie ?'),
  ('pages.faq.auto.paragraph.1y13o4g', '/faq', 'paragraph', 'Que se passe-t-il si mon client règle à 45 ou 60 jours ?'),
  ('pages.faq.auto.paragraph.1yh586d', '/faq', 'paragraph', 'À mettre une part de votre rémunération brute de côté. Vous pouvez ainsi lisser une paie d’un mois sur l’autre, financer des congés en maintenant votre rémunération, provisionner une fin de contrat ou débloquer un acompte selon vos besoins.'),
  ('pages.faq.auto.paragraph.2b6r0c', '/faq', 'paragraph', 'Trois acteurs et deux contrats. Vous trouvez et réalisez votre mission ; l’entreprise cliente signe un contrat de prestation avec The Porters ; The Porters vous salarie et transforme votre chiffre d’affaires en salaire. Vous gardez votre autonomie commerciale et bénéficiez du statut de salarié.'),
  ('pages.faq.auto.paragraph.2umxn3', '/faq', 'paragraph', 'Non. Votre contrat de travail suit vos missions, et aucune durée d’engagement ne vous est imposée. Les modalités de rupture sont celles du droit du travail.'),
  ('pages.faq.auto.paragraph.3zhd4m', '/faq', 'paragraph', 'Oui. Votre mission peut se dérouler en France ou à l’étranger, pour un client français ou étranger, sur site ou en télétravail.'),
  ('pages.faq.auto.paragraph.4w7xba', '/faq', 'paragraph', 'Mes droits au chômage sont-ils préservés ?'),
  ('pages.faq.auto.paragraph.5jkrsc', '/faq', 'paragraph', 'Suis-je engagé sur une durée minimale ?'),
  ('pages.faq.auto.paragraph.5mx0k7', '/faq', 'paragraph', 'Que se passe-t-il quand je veux partir ?'),
  ('pages.faq.auto.paragraph.5td047', '/faq', 'paragraph', 'Le simulateur vous donne une estimation à partir de votre TJM, de vos jours facturés et de vos frais professionnels. L’écart entre chiffre d’affaires et net vient de trois postes : les frais de gestion, les cotisations sociales et les frais professionnels remboursés. Le résultat reste indicatif jusqu’à validation de votre situation.'),
  ('pages.faq.auto.paragraph.80f4a9', '/faq', 'paragraph', 'Oui. Vous cotisez chaque mois à l’assurance chômage et vous ouvrez des droits comme tout salarié. En cas de rupture conventionnelle, vous pouvez prétendre à l’Aide au retour à l’emploi.'),
  ('pages.faq.auto.paragraph.86qv51', '/faq', 'paragraph', '27 réponses indexées'),
  ('pages.faq.auto.paragraph.8b990q', '/faq', 'paragraph', 'Quels métiers IT peuvent être portés ?'),
  ('pages.faq.auto.paragraph.956ws7', '/faq', 'paragraph', 'Y a-t-il un portage pour les salariés et un autre pour les freelances ?'),
  ('pages.faq.auto.paragraph.azhjsm', '/faq', 'paragraph', 'En cinq étapes : analyse du parcours réel, évaluation sur les référentiels métiers CIGREF, SYNTEC et ROME, deux entretiens structurés — RH et technique — puis tests ou mise en situation selon le périmètre, et enfin une validation interne. Les profils vous sont transmis sous forme anonymisée.'),
  ('pages.faq.auto.paragraph.bwdi4c', '/faq', 'paragraph', 'FAQ'),
  ('pages.faq.auto.paragraph.dm5q3p', '/faq', 'paragraph', 'Comment sont gérés les frais professionnels ?'),
  ('pages.faq.auto.paragraph.dm6a58', '/faq', 'paragraph', 'The Porters'),
  ('pages.faq.auto.paragraph.dsmb7i', '/faq', 'paragraph', '6 points'),
  ('pages.faq.auto.paragraph.e4rnal', '/faq', 'paragraph', 'Cinq familles de questions. Choisissez celle qui vous bloque.'),
  ('pages.faq.auto.paragraph.e6c4a7', '/faq', 'paragraph', 'Oui. Il est encadré par le Code du travail, par l’accord national interprofessionnel de 2008 et par l’ordonnance du 2 avril 2015. Ce cadre définit les droits et obligations du salarié porté, de l’entreprise cliente et de la société de portage.'),
  ('pages.faq.auto.paragraph.f11j3g', '/faq', 'paragraph', '7 points'),
  ('pages.faq.auto.paragraph.fae4wu', '/faq', 'paragraph', 'Chaque mois, selon la date à laquelle vous transmettez votre compte rendu d’activité. Deux sessions de paie existent ; votre conseiller vous indique les échéances applicables avant le démarrage.'),
  ('pages.faq.auto.paragraph.gnq14r', '/faq', 'paragraph', 'Les conditions de versement et l’impact du délai de règlement sont fixés avant le démarrage. Votre simulation et vos documents contractuels indiquent précisément le calendrier applicable.'),
  ('pages.faq.auto.paragraph.h7damr', '/faq', 'paragraph', 'Puis-je travailler pour un client à l’étranger ?'),
  ('pages.faq.auto.paragraph.hzhzo9', '/faq', 'paragraph', 'Que couvrent les frais de gestion ?'),
  ('pages.faq.auto.paragraph.i4i5ys', '/faq', 'paragraph', 'Combien mon TJM me laisse-t-il en net ?'),
  ('pages.faq.auto.paragraph.im93aj', '/faq', 'paragraph', 'Questions fréquentes'),
  ('pages.faq.auto.paragraph.iqq900', '/faq', 'paragraph', 'Votre cas est particulier ?'),
  ('pages.faq.auto.paragraph.j8nwm7', '/faq', 'paragraph', 'Que se passe-t-il entre deux missions ?'),
  ('pages.faq.auto.paragraph.lzme8t', '/faq', 'paragraph', 'Pourquoi passer par un consultant en portage salarial ?'),
  ('pages.faq.auto.paragraph.nigrj', '/faq', 'paragraph', '7 points'),
  ('pages.faq.auto.paragraph.o6596t', '/faq', 'paragraph', 'Combien de congés payés ai-je ?'),
  ('pages.faq.auto.paragraph.p4yker', '/faq', 'paragraph', 'The Porters. Le consultant reste salarié porté par The Porters pendant toute la mission, et vous n’avez qu’un interlocuteur contractuel.'),
  ('pages.faq.auto.paragraph.q08akm', '/faq', 'paragraph', 'Quel est votre taux de frais de gestion ?'),
  ('pages.faq.auto.paragraph.qjvio8', '/faq', 'paragraph', 'Ils vous sont remboursés lorsqu’ils sont réels, justifiés et liés à votre activité : internet, téléphone, matériel, logiciels, déplacements, repas ou hébergement selon la situation. Ils ne sont pas financés par les frais de gestion — ce sont deux choses distinctes.'),
  ('pages.faq.auto.paragraph.qrkykr', '/faq', 'paragraph', 'Une question ?'),
  ('pages.faq.auto.paragraph.s5fd6o', '/faq', 'paragraph', 'Vous ne créez pas de société et vous ne produisez aucun document administratif. Vous conservez une couverture sociale de salarié — chômage et retraite complémentaire comprises — là où la micro-entreprise n’en ouvre pas. En contrepartie, des frais de gestion sont prélevés sur votre chiffre d’affaires, et vous restez responsable de votre prospection et de votre TJM.'),
  ('pages.faq.auto.paragraph.tfnra7', '/faq', 'paragraph', 'Statut, rémunération, frais, congés, aléas, entrée et sortie. Chaque réponse commence par la réponse — la nuance vient après.'),
  ('pages.faq.auto.paragraph.u6n49f', '/faq', 'paragraph', 'Comment sélectionnez-vous les profils ?'),
  ('pages.faq.auto.paragraph.uhxdi5', '/faq', 'paragraph', 'Toutes les prestations intellectuelles : cybersécurité, développement, DevOps, cloud, data engineering, IA, Product Ownership, Scrum Master, coaching agile, chefferie de projet IT, AMOA et conseil. Seules les professions réglementées et les services à la personne sont exclus.'),
  ('pages.faq.auto.paragraph.uv5vtp', '/faq', 'paragraph', 'Quelle différence avec la micro-entreprise ou la SASU ?'),
  ('pages.faq.auto.paragraph.vh65fw', '/faq', 'paragraph', 'Thème'),
  ('pages.faq.auto.paragraph.vwhw5u', '/faq', 'paragraph', 'Vous partez quand vous voulez : démission, rupture de période d’essai ou rupture conventionnelle. Nous vous remettons le solde de tout compte, le certificat de travail, l’attestation destinée à France Travail et le reçu pour solde de tout compte. Une rupture conventionnelle suppose des fonds suffisants sur votre compte de trésorerie pour couvrir la prime et les frais associés.'),
  ('pages.faq.auto.paragraph.wnjcn', '/faq', 'paragraph', 'Vous percevez des indemnités journalières de la Sécurité sociale, comme tout salarié, puis la prévoyance prend le relais sur les arrêts longs. Les paramètres exacts vous sont confirmés par le service paie.'),
  ('pages.faq.auto.paragraph.xy7oki', '/faq', 'paragraph', 'Thème'),
  ('pages.faq.auto.paragraph.ynlp6m', '/faq', 'paragraph', 'Non, aucune mission n’est garantie. Nous vous proposons des missions issues de nos partenaires, et vous restez libre de trouver les vôtres. Nous intervenons aussi sur votre positionnement, la présentation de votre offre et le cadrage de vos opportunités.'),
  ('pages.faq.auto.paragraph.zk8xw1', '/faq', 'paragraph', 'Le taux appliqué figure dans votre simulation et dans les documents contractuels avant la signature. Il est prélevé sur votre chiffre d’affaires mensuel et finance les services détaillés sur la page Frais et rémunération.'),
  ('pages.home.auto.button.1518vu2', '/', 'button', 'Y a-t-il un portage pour les salariés et un autre pour les freelances ?<span aria-hidden="true" data-astro-cid-lcdefpme="">+</span>'),
  ('pages.home.auto.button.1x3km95', '/', 'button', 'Quels métiers IT peuvent être portés ?<span aria-hidden="true" data-astro-cid-lcdefpme="">+</span>'),
  ('pages.home.auto.button.br0k1o', '/', 'button', 'Comment fonctionne le portage salarial ?<span aria-hidden="true" data-astro-cid-lcdefpme="">+</span>'),
  ('pages.home.auto.button.y89i57', '/', 'button', 'Le portage salarial est-il reconnu légalement ?<span aria-hidden="true" data-astro-cid-lcdefpme="">+</span>'),
  ('pages.home.auto.paragraph.16t4hk9', '/', 'paragraph', 'Safrana Chloé'),
  ('pages.home.auto.paragraph.1bgetsm', '/', 'paragraph', 'Yoann Deroux'),
  ('pages.home.auto.paragraph.1oiw3d2', '/', 'paragraph', 'Non. Il n’existe qu’un seul portage salarial. Que vous veniez d’un CDI, d’une micro-entreprise ou d’une SASU, le mécanisme est identique : un contrat de travail avec nous, un contrat de prestation avec votre client. Ce qui change, c’est votre point de départ, pas le dispositif.'),
  ('pages.home.auto.paragraph.1te9ygs', '/', 'paragraph', 'Avis publié sur Google'),
  ('pages.home.auto.paragraph.5uo77x', '/', 'paragraph', 'Consulter les avis vérifiés'),
  ('pages.home.auto.paragraph.8peni1', '/', 'paragraph', 'Toutes les prestations intellectuelles : cybersécurité, développement, DevOps, cloud, data engineering, IA, Product Ownership, Scrum Master, coaching agile, chefferie de projet IT, AMOA et conseil. Seules les professions réglementées et les services à la personne sont exclus.'),
  ('pages.home.auto.paragraph.9b2ihv', '/', 'paragraph', 'Oui. Il est encadré par le Code du travail, par l’accord national interprofessionnel de 2008 et par l’ordonnance du 2 avril 2015. Ce cadre définit les droits et obligations du salarié porté, de l’entreprise cliente et de la société de portage.'),
  ('pages.home.auto.paragraph.q2a4ud', '/', 'paragraph', 'Avis publié sur Google'),
  ('pages.home.auto.paragraph.qrkykr', '/', 'paragraph', 'Une question ?'),
  ('pages.home.auto.paragraph.qzu6ee', '/', 'paragraph', 'Avis Google'),
  ('pages.home.auto.paragraph.rim4ik', '/', 'paragraph', 'Mylène Pernin'),
  ('pages.home.auto.paragraph.s2lxe8', '/', 'paragraph', 'Trois acteurs et deux contrats. Vous trouvez et réalisez votre mission ; l’entreprise cliente signe un contrat de prestation avec The Porters ; The Porters vous salarie et transforme votre chiffre d’affaires en salaire. Vous gardez votre autonomie commerciale et bénéficiez du statut de salarié.'),
  ('pages.home.auto.paragraph.x266uz', '/', 'paragraph', 'Avis publié sur Google'),
  ('pages.home.auto.quote.evzsht', '/', 'quote', '« Contact réactif, agréable et disponible pour accompagner les échanges. »'),
  ('pages.home.auto.quote.roxvnn', '/', 'quote', '« Un accompagnement exemplaire sur le coaching, le suivi et la partie administrative. »'),
  ('pages.home.auto.quote.tbna0o', '/', 'quote', '« Une équipe engagée, claire et toujours disponible pour le portage salarial. »'),
