  ('pages.livres-blancs.auto.heading.125080', '/livres-blancs', 'heading', 'Comparatif des statuts pour freelances'),
  ('pages.livres-blancs.auto.heading.15w4wyl', '/livres-blancs', 'heading', 'Guide complet du portage salarial'),
  ('pages.livres-blancs.auto.heading.1ozy636', '/livres-blancs', 'heading', 'Des ressources pour <span class="gold-underline">décider avec méthode</span>'),
  ('pages.livres-blancs.auto.heading.rnxlm7', '/livres-blancs', 'heading', 'Checklist pour démarrer en portage salarial'),
  ('pages.livres-blancs.auto.paragraph.18e88jx', '/livres-blancs', 'paragraph', 'Vérifier votre mission, votre TJM, l’accord du client, les documents nécessaires et les points à clarifier avant la contractualisation.'),
  ('pages.livres-blancs.auto.paragraph.1a02ixi', '/livres-blancs', 'paragraph', 'Checklist'),
  ('pages.livres-blancs.auto.paragraph.1fwvrar', '/livres-blancs', 'paragraph', 'Comprendre la relation tripartite, les contrats, la facturation, la paie et les vérifications à effectuer avant de démarrer.'),
  ('pages.livres-blancs.auto.paragraph.1id3tdl', '/livres-blancs', 'paragraph', 'Livres blancs'),
