  ('pages.portage-salarial.auto.heading.1nsallb', '/portage-salarial', 'heading', 'Libre dans la mission. Salarié dans le cadre.'),
  ('pages.portage-salarial.auto.heading.1ot5ix6', '/portage-salarial', 'heading', 'Quel cadre correspond à votre projet ?'),
  ('pages.portage-salarial.auto.heading.1xptkyn', '/portage-salarial', 'heading', 'Vous exercez votre métier. Nous tenons le cadre.'),
  ('pages.portage-salarial.auto.heading.irt5ms', '/portage-salarial', 'heading', 'Une vision du portage, au plus près des talents'),
  ('pages.portage-salarial.auto.heading.op6xj4', '/portage-salarial', 'heading', 'Un interlocuteur vous suit'),
  ('pages.portage-salarial.auto.heading.pf0mxl', '/portage-salarial', 'heading', 'Trois acteurs. Deux contrats. Une mission.'),
  ('pages.portage-salarial.auto.heading.vw0zme', '/portage-salarial', 'heading', 'Vous devenez salarié'),
  ('pages.portage-salarial.auto.heading.wsfrw1', '/portage-salarial', 'heading', 'Nous gérons le cadre'),
  ('pages.portage-salarial.auto.paragraph.10n12s0', '/portage-salarial', 'paragraph', 'Comprendre le portage'),
  ('pages.portage-salarial.auto.paragraph.1264m40', '/portage-salarial', 'paragraph', 'Contrat, facturation, paie et déclarations.'),
  ('pages.portage-salarial.auto.paragraph.13i353e', '/portage-salarial', 'paragraph', 'Vous trouvez vos clients, négociez votre TJM et pilotez votre intervention.'),
  ('pages.portage-salarial.auto.paragraph.17ysdw7', '/portage-salarial', 'paragraph', 'Le mécanisme'),
