  ('pages.qui-sommes-nous.auto.paragraph.1nzigs2', '/qui-sommes-nous', 'paragraph', 'Un échange suffit pour identifier le bon cadre et la prochaine étape.'),
  ('pages.qui-sommes-nous.auto.paragraph.1sve2ab', '/qui-sommes-nous', 'paragraph', 'Le groupe Porters'),
  ('pages.qui-sommes-nous.auto.paragraph.36ekrk', '/qui-sommes-nous', 'paragraph', 'Nous accompagnons les consultants qui veulent exercer librement et les entreprises qui cherchent une expertise qualifiée. Le statut change ; l’exigence de clarté reste la même.'),
  ('pages.qui-sommes-nous.auto.paragraph.fboy7h', '/qui-sommes-nous', 'paragraph', 'Contrats, frais, facturation et paie sont expliqués avant le démarrage.'),
  ('pages.qui-sommes-nous.auto.paragraph.ftgsoc', '/qui-sommes-nous', 'paragraph', 'L’ESN spécialisée IT'),
  ('pages.qui-sommes-nous.auto.paragraph.gfzgru', '/qui-sommes-nous', 'paragraph', 'The Porters est adhérente à la Fédération des Entreprises de Portage Salarial. Le portage salarial est encadré par le Code du travail, l’accord national interprofessionnel de 2008 et l’ordonnance du 2 avril 2015.'),
  ('pages.qui-sommes-nous.auto.paragraph.qrkykr', '/qui-sommes-nous', 'paragraph', 'Une question ?'),
