  ('pages.qui-sommes-nous.auto.paragraph.uw4yti', '/qui-sommes-nous', 'paragraph', 'Nous partons du rôle, de l’environnement technique et des responsabilités réelles.'),
  ('pages.qui-sommes-nous.auto.paragraph.wxzqyn', '/qui-sommes-nous', 'paragraph', 'Pour les consultants qui ont trouvé leur mission et veulent conserver leur autonomie avec un contrat de travail, une paie et une protection sociale.'),
