  ('pages.rendez-vous.auto.paragraph.15g49b5', '/rendez-vous', 'paragraph', '30 min'),
  ('pages.rendez-vous.auto.paragraph.16b4gq', '/rendez-vous', 'paragraph', 'La personne que vous avez au téléphone est celle qui suivra votre dossier ensuite.'),
  ('pages.rendez-vous.auto.paragraph.17cb27i', '/rendez-vous', 'paragraph', '45 min'),
  ('pages.rendez-vous.auto.paragraph.17s4a1v', '/rendez-vous', 'paragraph', 'Ce que vous obtenez'),
  ('pages.rendez-vous.auto.paragraph.1dgbg55', '/rendez-vous', 'paragraph', 'Une mission cyber, data, IA, cloud, DevOps, produit ou agilité déjà identifiée à cadrer.'),
  ('pages.rendez-vous.auto.paragraph.1dttx4h', '/rendez-vous', 'paragraph', 'Nous arrivons avec votre simulation relue et les points à trancher, pas avec une présentation générique.'),
